// Z1 menu session for the AF-ON chooser face work.
// The Z1 overlay, registration, binding, redirects and value hooks are the baseline.
// opts.one, when set, is the single extra change. Do not edit this file after it has run.
import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL, fileURLToPath } from 'node:url';

const UI = 0x3d6f;
const BASE = 0x60021020;
const PROFILE = 0xa031e920;
const PROFILE_CACHED = 0x6031e920;
const PAGE27 = 0x6158f0f8;
const SOURCE = 0x61529ce8;
const TABLE_PTR = 0x6150f5f0;
const TABLE_RAM = 0x6031ea00;
const ROW = 0x6031e978;
const DESC = 0x6031e9a0;
const DESC_2154 = 0x6062132c;
const DESC_238 = 0x606200e4;
const NODE = 0x6031e9b8;
const BUCKET_BASE = 0x62a84970;
const STOCK_ROW = 0x6158dc44;
const STOCK_TABLE = 0x6150c514;
const BIND_SRC = 0x615c540c;
const BIND_COUNT = 416;
const BIND_RAM = 0x60320000;
const DIR = 0x615cc934;
const REC_2154 = 0x615c5e14;
const ZONE_LIST = 0x6158ba1c;
const PRIORITY_LIST = 0x6158ba04;

const HOME_KEYS = [
  ['0x99d2', 0x99d2, 3], ['0x9fa1', 0x9fa1, 3], ['0xdfa1', 0xdfa1, 1], ['0x1ea1', 0x1ea1, 1],
  ['0x9ec1', 0x9ec1, 1], ['0x9ed1', 0x9ed1, 1], ['0x9ee1', 0x9ee1, 1], ['0x9ef1', 0x9ef1, 1], ['0x59b1', 0x59b1, 1],
];
const ORIGINALLY = [2274, 2275, 2276, 2277, 2278, 2279];

function fileHash(p) {
  const data = readFileSync(p);
  return { path: p.replace(/\\/g, '/'), sha256: createHash('sha256').update(data).digest('hex'), bytes: data.length };
}

export async function runSession(opts) {
  const { checkout, outPath, tag, explanation, change } = opts;
  assert(checkout && outPath && tag && explanation && change);
  const one = opts.one ?? null;
  if (one) {
    assert(one.type && one.label && one.explanation);
    assert(['alternate', 'row-kind', 'overlay', 'runtime'].includes(one.type));
  }
  process.env.OM_EMU_MODEL = 'E147';
  const use = (p) => import(pathToFileURL(resolve(checkout, 'emu', p)).href);
  const helperRels = [
    'checks/lib/env.mjs', 'src/fw/model.mjs', 'src/lab/player.mjs', 'src/lab/play.mjs',
    'scenarios/session_replay.mjs', 'src/lab/menuwalk.mjs', 'checks/lib/png.mjs', 'src/lab/display.mjs',
  ];
  const helpers = helperRels.map((rel) => fileHash(resolve(checkout, 'emu', rel)));
  helpers.push(fileHash(fileURLToPath(import.meta.url)));
  const { loadNand, patchedFirmware, createHash: emuHash, ORIGINAL, BLOCK, NAND } = await use('checks/lib/env.mjs');
  const { IMAGE_BASE } = await use('src/fw/model.mjs');
  const { Player } = await use('src/lab/player.mjs');
  const { UIIN_ENTRIES, apply_uiin_layout, uiin_layout } = await use('src/lab/play.mjs');
  const { PLAYER_PARSER } = await use('scenarios/session_replay.mjs');
  const { MenuWalk } = await use('src/lab/menuwalk.mjs');
  const { write_png } = await use('checks/lib/png.mjs');
  const { words_to_rgb } = await use('src/lab/display.mjs');
  const resources = [ORIGINAL, BLOCK, NAND, resolve('inputs/00_0100_50000020.decoded.bin'),
    resolve('ref/tasks/T3a-afon-zone-row/run-20261118-053855/work/out/overlay-changed-bytes.csv')]
    .filter(Boolean).map((p) => fileHash(p));

  const lines = [];
  const emit = (role, x) => {
    const row = { hook: role === 'behaviour' ? 'EMULATOR-ONLY' : 'observe', role, ...x };
    lines.push(JSON.stringify(row));
    console.log(JSON.stringify(row));
  };
  const native = (address) => (0x50000000 + address - IMAGE_BASE) >>> 0;
  const hex = (v) => (v === null || v === undefined) ? null : '0x' + (v >>> 0).toString(16);
  emit('observe', {
    step: 'helper-hashes',
    note: 'SHA-256 of this session module and of each helper and firmware file it reads, taken at this run.',
    helpers, resources,
  });

  const image = readFileSync(resolve('inputs/00_0100_50000020.decoded.bin'));
  const stockRow = Buffer.from(image.subarray(STOCK_ROW - BASE, STOCK_ROW - BASE + 36));
  assert.equal(stockRow.readUInt32LE(12), PRIORITY_LIST);
  assert.equal(stockRow.readUInt32LE(16), 2);
  assert.equal(stockRow.readUInt16LE(4), 12);
  assert.equal(stockRow.readUInt32LE(28), 0);
  assert.equal(stockRow.readUInt32LE(32), 0);

  const bindSrc = image.subarray(BIND_SRC - BASE, BIND_SRC - BASE + BIND_COUNT * 24);
  const used = new Set();
  for (let i = 0; i < BIND_COUNT; i++) used.add(bindSrc.readUInt32LE(i * 24));
  let newId = null;
  for (const cand of [0x1e6, 0x1e7, 0x0e3d, 0x3d6f]) if (!used.has(cand)) { newId = cand; break; }
  if (newId === null) throw new Error('no free editor id');
  const extra = Buffer.from(image.subarray(REC_2154 - BASE, REC_2154 - BASE + 24));
  extra.writeUInt32LE(newId, 0);
  extra.writeUInt32LE(UI, 8);
  const bindBytes = Buffer.concat([bindSrc, extra]);

  const csvPath = resolve('ref/tasks/T3a-afon-zone-row/run-20261118-053855/work/out/overlay-changed-bytes.csv');
  const byOff = new Map();
  for (const row of readFileSync(csvPath, 'utf8').trim().split(/\r?\n/).slice(1)) {
    const [o, , old, next] = row.split(',');
    byOff.set(parseInt(o, 16), { old: parseInt(old, 16), neu: parseInt(next, 16), purpose: 'prerequisite section-1 tail from the T3a row overlay' });
  }
  const descBytes = Buffer.from(image.subarray(DESC_238 - BASE, DESC_238 - BASE + 20));
  descBytes.writeUInt16LE(UI, 0);
  for (let i = 0; i < 20; i++) byOff.set((DESC - BASE) + i, { old: image[(DESC - BASE) + i], neu: descBytes[i], purpose: 'Z1 descriptor id 0x3D6F cloned from UI 238' });
  const rowBytes = Buffer.from(stockRow);
  rowBytes.writeUInt32LE(UI, 0);
  rowBytes.writeUInt32LE(ZONE_LIST, 12);
  rowBytes.writeUInt32LE(10, 16);
  if (one && one.type === 'alternate') {
    rowBytes.writeUInt32LE(one.ptr >>> 0, 28);
    rowBytes.writeUInt32LE(one.count >>> 0, 32);
  }
  if (one && one.type === 'row-kind') rowBytes.writeUInt16LE(one.kind & 0xffff, 4);
  for (let i = 0; i < 36; i++) {
    const addr = ROW + i;
    let purpose = 'Z1 third row copied from 2154 with UI id 0x3D6F; primary list 0x6158ba1c count 10; alternate 0';
    if (addr >= ROW + 12 && addr < ROW + 20) purpose = 'Z1 row primary list 0x6158ba1c count 10';
    if (one && one.type === 'alternate' && addr >= ROW + 28 && addr < ROW + 36) purpose = 'one change: row alternate pointer and count';
    if (one && one.type === 'row-kind' && addr >= ROW + 4 && addr < ROW + 6) purpose = 'one change: row kind';
    byOff.set((ROW - BASE) + i, { old: image[(ROW - BASE) + i], neu: rowBytes[i], purpose });
  }
  if (one && one.type === 'overlay') {
    for (const w of one.writes) {
      for (let i = 0; i < w.bytes.length; i++) {
        const addr = (w.addr + i) >>> 0;
        const o = addr - BASE;
        byOff.set(o, { old: image[o], neu: w.bytes[i] & 0xff, purpose: w.purpose });
      }
    }
  }
  const stockTable = image.subarray(STOCK_TABLE - BASE, STOCK_TABLE - BASE + 48);
  const third = Buffer.from(stockTable.subarray(0, 24));
  third[4] = 0x6f; third[5] = 0x3d;
  third.writeUInt32LE(newId, 16);
  const tableBytes = Buffer.concat([stockTable, third]);
  for (let i = 0; i < 72; i++) {
    const o = (TABLE_RAM - BASE) + i;
    if (image[o] !== 0xff) throw new Error('action slot is not FF at ' + hex(BASE + o));
    byOff.set(o, { old: 0xff, neu: tableBytes[i], purpose: 'page-27 action table; third record editor id 0x1e6' });
  }
  const ordered = [...byOff.entries()].sort((a, b) => a[0] - b[0]);
  const patches = [];
  const csvRows = ['component_offset,runtime_address,stock_byte,proposed_byte,purpose'];
  for (const [off, rec] of ordered) {
    if (image[off] !== rec.old) throw new Error('overlay old mismatch at ' + hex(BASE + off));
    const last = patches.at(-1);
    if (last && off === last.offset + last.old.length && last.purpose === rec.purpose) { last.old.push(rec.old); last.neu.push(rec.neu); }
    else patches.push({ offset: off, old: [rec.old], neu: [rec.neu], purpose: rec.purpose });
    csvRows.push([off.toString(16).padStart(8, '0'), (BASE + off).toString(16), rec.old.toString(16).padStart(2, '0'), rec.neu.toString(16).padStart(2, '0'), rec.purpose].join(','));
  }
  const csvName = 'work/out/overlay-' + tag + '.csv';
  writeFileSync(resolve(csvName), csvRows.join('\n') + '\n');
  if (opts.canonical) writeFileSync(resolve('work/out/overlay-changed-bytes.csv'), csvRows.join('\n') + '\n');
  const fw = patchedFirmware(patches.map((x, n) => ({
    block: 'main', offset: x.offset, old: Uint8Array.from(x.old), new: Uint8Array.from(x.neu), source: 'work/scripts/session_h1.mjs', n,
  })));
  const layout = uiin_layout(fw.rom);
  const keyEntry = (code) => {
    const entries = layout.groups.flatMap(({ entries }, group) => entries.filter(([, , candidate]) => candidate === code).map((entry) => [group, ...entry]));
    assert.equal(entries.length, 1, 'key entries for ' + hex(code));
    return entries[0];
  };
  apply_uiin_layout(fw.rom);
  const parked = keyEntry(0x120b);
  UIIN_ENTRIES.set(parked.slice(0, 3).join(','), parked);
  const pl = new Player(
    { ...PLAYER_PARSER, no_browser: true, idle: 'off', a15: 'on', out: '<out>', no_wait_on_error: true },
    { ...fw, nand: loadNand(), createHash: emuHash, wallClock: () => performance.now() / 1000, machine: { coverage: { mark() {}, stub() {} } }, patch: fw.summary, patchRanges: fw.changed, loaded: 'on' },
  );
  pl.camapp_components = true;
  pl.camapp_native_tra = true;
  let sessionPlayer = pl;
  try {
    sessionPlayer.open_session();
    const s = pl.session;
    const l = s.lab;
    const bytes = (addr, n) => Buffer.from(l.sim.read(addr, n)).toString('hex');
    const readByte = (addr) => l.sim.read(addr, 1)[0];
    const writeByte = (addr, value) => { const b = Buffer.alloc(1); b[0] = value & 0xff; l.sim.write(addr, b); };
    const writeU32 = (addr, value) => { const b = Buffer.alloc(4); b.writeUInt32LE(value >>> 0, 0); l.sim.write(addr, b); };
    const writeU16 = (addr, value) => { const b = Buffer.alloc(2); b.writeUInt16LE(value & 0xffff, 0); l.sim.write(addr, b); };
    const word = (addr) => { try { return l.sim.u32(addr) >>> 0; } catch { return null; } };
    const half = (addr) => { try { const b = l.sim.read(addr, 2); return b[0] | (b[1] << 8); } catch { return null; } };
    const gate = { reading: false };
    const state = { phase: 'off', group: 'boot' };
    const live = () => !gate.reading && state.phase === 'on';
    emit('behaviour', {
      step: 'explanation', tag, explanation, change,
      one: one ? { type: one.type, label: one.label, explanation: one.explanation } : null,
      descriptor: descBytes.toString('hex'),
      row: rowBytes.toString('hex'),
      newEditorId: hex(newId),
      thirdRecord: tableBytes.subarray(48, 72).toString('hex'),
    });
    emit('behaviour', {
      step: 'harness-120b',
      label: 'EMULATOR-ONLY harness override. UIIN_ENTRIES.set installs the 0x120b matrix entry. That code is only in UI_IN variant 1; the lab board reads variant 0.',
      code: '0x120b',
    });
    emit('behaviour', {
      step: 'overlay-load',
      label: 'EMULATOR-ONLY Z1 overlay. Prerequisite T3a section-1 tail, action table, third row, UI 238 descriptor clone.',
      bytes: ordered.length, csv: csvName,
    });
    const own = (r) => (r.d0 & 0xffff) === UI;
    const bucket = { compares: [], setters: [], store63431: [], store63380: [], conversion: [] };
    const totals = { compares: 0, setters: 0, store63431: 0, store63380: 0, conversion: 0, chooser: 0 };
    const dropped = { compares: 0, setters: 0, store63431: 0, store63380: 0, conversion: 0 };
    const CAP = 100000;
    const pushCap = (key, rec) => {
      totals[key] += 1;
      if (bucket[key].length >= CAP) { dropped[key] += 1; return; }
      bucket[key].push(rec);
    };
    l.hook(native(0x6041931e), (h, r) => {
      if (!own(r)) { l.passthrough(r); return; }
      h.finish(r, { d0: readByte(PROFILE) });
    }, 'EMULATOR-ONLY afon value getter');
    l.hook(native(0x6041937f), (h, r) => {
      const rec = { id: r.d0 & 0xffff, value: r.d1 & 0xffff, d0: r.d0 >>> 0, d1: r.d1 >>> 0, caller: hex(r.mdr >>> 0) };
      if (live()) pushCap('setters', rec);
      if (!own(r)) { l.passthrough(r); return; }
      writeByte(PROFILE, r.d1 & 0xff);
      writeByte(PROFILE_CACHED, r.d1 & 0xff);
      h.finish(r, { d0: 0 });
    }, 'EMULATOR-ONLY afon setter');
    l.hook(native(0x60419446), (h, r) => {
      if (!own(r)) { l.passthrough(r); return; }
      h.finish(r, { d0: 0xA70F });
    }, 'EMULATOR-ONLY afon mapped getter');
    l.hook(native(0x60419696), (h, r) => {
      if (!own(r)) { l.passthrough(r); return; }
      h.finish(r, { d0: 0 });
    }, 'EMULATOR-ONLY afon index getter');
    emit('behaviour', {
      step: 'value-hooks',
      label: 'EMULATOR-ONLY T3a value hooks for 0x3D6F',
      getter: '0x6041931e returns the byte at 0xa031e920',
      setter: '0x6041937f writes D1 low byte to 0xa031e920 and 0x6031e920 and returns 0',
      mapped: '0x60419446 returns 0xA70F',
      index: '0x60419696 returns 0',
      otherIds: 'passthrough',
    });
    if (opts.fullTrace) {
      l.observe(native(0x611a26e1), (lab, r) => {
        if (!live()) return;
        const rec = r.a2 >>> 0;
        pushCap('compares', { d0: r.d0 & 0xffff, d1: r.d1 & 0xffff, a2: hex(rec), bytes: bytes(rec, 24) });
      }, 'obs-compare');
      l.observe(native(0x6124f523), (lab, r) => {
        if (!live()) return;
        const d0 = r.d0 >>> 0;
        const d1 = r.d1 & 0xffff;
        const a2 = r.a2 >>> 0;
        const rec = { d0, d1, a2: hex(a2), match: d0 === d1 };
        if (rec.match) { rec.bytes = bytes(a2, 24); rec.ui = word(a2 + 8); }
        pushCap('conversion', rec);
      }, 'obs-convert');
      l.observe(native(0x60063431), (lab, r) => {
        if (!live()) return;
        pushCap('store63431', { d0: r.d0 >>> 0, d1: r.d1 >>> 0, d2: r.d2 >>> 0, caller: hex(r.mdr >>> 0) });
      }, 'obs-store-63431');
      l.observe(native(0x60063380), (lab, r) => {
        if (!live()) return;
        pushCap('store63380', { d0: r.d0 >>> 0, d1: r.d1 >>> 0, caller: hex(r.mdr >>> 0) });
      }, 'obs-store-63380');
    }
    l.observe(native(0x610e2536), () => {
      if (!live()) return;
      totals.chooser += 1;
    }, 'obs-chooser');
    const faceKeys = [];
    l.observe(native(0x611f7f01), (lab, r) => {
      if (!live() || faceKeys.length > 40) return;
      const srcAddr = r.a1 >>> 0;
      try {
        faceKeys.push({
          at: 'entry', caller: hex(r.mdr >>> 0), a0: hex(r.a0 >>> 0), a1: hex(srcAddr),
          keyHalf: half(srcAddr + 4), head: bytes(srcAddr, 24),
        });
      } catch { /* unmapped source */ }
    }, 'obs-face-key');
    l.observe(native(0x611f7f40), (lab, r) => {
      if (!live() || faceKeys.length > 40) return;
      const rec = r.a2 >>> 0;
      try {
        const widget = r.a3 >>> 0;
        const parent = word(widget + 0x998);
        faceKeys.push({
          at: 'match', record: hex(rec), key: half(rec), count: half(rec + 8),
          face: hex(word(rec + 0xc)), help: hex(word(rec + 0x10)), caller: hex(r.mdr >>> 0),
          widget: hex(widget), parent: hex(parent), parentHead: bytes(parent, 48),
          near: bytes(widget + 0x980, 48),
        });
      } catch { /* unmapped record */ }
    }, 'obs-face-record');
    const faces = new Map();
    const seen7785 = new Map();
    const seen782f = new Map();
    let faceN = 0;
    let faceDrop = 0;
    let pending = null;
    const FACE_CAP = 400;
    const faceKey = (rec) => [rec.fn, rec.caller, rec.list ?? '', rec.record ?? '', rec.value ?? '', rec.count ?? '',
      rec.face ? rec.face.kind : (rec.kind0 ?? ''), rec.face ? rec.face.id : (rec.id2 ?? '')].join('|');
    const noteFace = (rec) => {
      faceN += 1;
      const key = faceKey(rec);
      const prev = faces.get(key);
      if (prev) { prev.n += 1; return prev; }
      if (faces.size >= FACE_CAP) { faceDrop += 1; return rec; }
      const stored = { ...rec, n: 1 };
      faces.set(key, stored);
      return stored;
    };
    const flushPending = () => {
      if (!pending) return;
      seen7785.set(pending.quick, noteFace(pending));
      pending = null;
    };
    l.observe(native(0x611c7785), (lab, r) => {
      if (!live()) return;
      try { face7785(r); } catch { /* a face sample that cannot be read is skipped */ }
    }, 'obs-face-7785');
    const face7785 = (r) => {
      flushPending();
      const list = r.a1 >>> 0;
      const quick = [r.mdr >>> 0, list, r.d0 >>> 0, r.d1 & 0xffff].join('|');
      const hit = seen7785.get(quick);
      if (hit) { hit.n += 1; faceN += 1; return; }
      const obj = r.a0 >>> 0;
      const slots = {};
      for (const off of [0xfc, 0x100, 0x104, 0x108]) {
        const p = word(obj + off);
        if (!p) continue;
        slots['+' + off.toString(16)] = { p: hex(p), list: hex(word(p)), count: half(p + 4) };
      }
      pending = {
        fn: '611c7785', quick, caller: hex(r.mdr >>> 0), value: r.d0 >>> 0, count: r.d1 & 0xffff,
        list: hex(list), head: list > 0x1000 ? bytes(list, 12) : null, obj: hex(obj), slots, face: null, n: 1,
      };
    };
    l.observe(native(0x611c77a1), (lab, r) => {
      if (!live() || !pending || pending.face) return;
      try { faceMatch(r); } catch { pending = null; }
    }, 'obs-face-match');
    const faceMatch = (r) => {
      const a2 = r.a2 >>> 0;
      pending.face = {
        kind: r.d0 & 0xffff, id: half(a2 + 2), value: word(a2 - 4),
        record: hex((a2 - 4) >>> 0), class: hex(word(a2 + 4)),
      };
      seen7785.set(pending.quick, noteFace(pending));
      pending = null;
    };
    l.observe(native(0x611c782f), (lab, r) => {
      if (!live()) return;
      try { face782f(r); } catch { /* unreadable record */ }
    }, 'obs-face-782f');
    const face782f = (r) => {
      const rec = r.a1 >>> 0;
      const kind0 = half(rec);
      const id2 = half(rec + 2);
      const quick = [r.mdr >>> 0, rec, kind0, id2].join('|');
      const hit = seen782f.get(quick);
      if (hit) { hit.n += 1; faceN += 1; return; }
      const row = {
        fn: '611c782f', caller: hex(r.mdr >>> 0), record: hex(rec), dest: hex(r.d0 >>> 0),
        kind0, id2, word4: hex(word(rec + 4)), n: 1,
      };
      seen782f.set(quick, noteFace(row));
    };
    const takeFaces = () => {
      flushPending();
      const rows = [...faces.values()].map(({ quick, ...rest }) => rest);
      faces.clear();
      const out = { n: faceN, dropped: faceDrop, rows };
      faceN = 0; faceDrop = 0;
      return out;
    };
    const readKey = (key, index) => {
      const saved = l.sim.registers();
      gate.reading = true;
      try { return l.call(native(0x60063380), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff; }
      finally { gate.reading = false; l.sim.reset(saved); }
    };
    const mapOf = (id) => {
      const saved = l.sim.registers();
      gate.reading = true;
      try {
        const key = l.call(native(0x60419446), { d0: id }, null, null, 200000).d0 & 0xffff;
        const index = l.call(native(0x60419696), { d0: id }, null, null, 200000).d0 & 0xffff;
        return { id, key, index };
      } finally { gate.reading = false; l.sim.reset(saved); }
    };
    const cells = () => {
      if (!opts.cells) return { profile: readByte(PROFILE), profileCached: readByte(PROFILE_CACHED) };
      const home = {};
      for (const [name, key, n] of HOME_KEYS) home[name] = Array.from({ length: n }, (_, i) => readKey(key, i));
      const originally = ORIGINALLY.map((id) => ({ ...mapOf(id) }));
      return {
        profile: readByte(PROFILE), profileCached: readByte(PROFILE_CACHED),
        k90a1: [readKey(0x90a1, 0), readKey(0x90a1, 1)],
        k1dd1: Array.from({ length: 10 }, (_, i) => readKey(0x1dd1, i)),
        k99a1: Array.from({ length: 8 }, (_, i) => readKey(0x99a1, i)),
        k9a41: readKey(0x9a41, 0),
        k5962: Array.from({ length: 6 }, (_, i) => readKey(0x5962, i)),
        home, originally,
      };
    };
    const take = () => {
      const snap = {
        setters: bucket.setters, compares: bucket.compares, store63431: bucket.store63431,
        store63380Count: bucket.store63380.length, conversion: bucket.conversion.filter((r) => r.match),
        faceKeys: faceKeys.splice(0, faceKeys.length),
      };
      for (const k of Object.keys(bucket)) bucket[k] = [];
      return { truncation: { cap: CAP, dropped: { ...dropped } }, totals: { ...totals }, ...snap, faces: takeFaces() };
    };
    const lookup = (label) => {
      const saved = l.sim.registers();
      let result = null;
      let error = null;
      gate.reading = true;
      try { result = l.call(native(0x604058bc), { d0: UI }, null, null, 2000000); }
      catch (e) { error = String(e && e.message || e); }
      const after = l.sim.registers();
      gate.reading = false;
      l.sim.reset(saved);
      emit('observe', { step: label, fn: '0x604058bc', d0: after.d0 >>> 0, a0: hex(after.a0 >>> 0), result, error });
    };
    lookup('descriptor-before-link');
    const bucketAddr = BUCKET_BASE + (UI & 0x7f) * 4;
    const head = word(bucketAddr);
    const nodeBytes = Buffer.alloc(8);
    nodeBytes.writeUInt32LE(DESC, 0);
    nodeBytes.writeUInt32LE(head >>> 0, 4);
    l.sim.write(NODE, nodeBytes);
    writeU32(bucketAddr, NODE);
    emit('behaviour', {
      step: 'descriptor-link',
      label: 'EMULATOR-ONLY hash link of the descriptor at 0x6031e9a0',
      descriptor: bytes(DESC, 20), node: hex(NODE), bucket: hex(bucketAddr), previousHead: hex(head >>> 0),
    });
    lookup('descriptor-after-link');
    l.sim.write(BIND_RAM, bindBytes);
    writeU32(DIR + 4, BIND_RAM);
    writeU16(DIR + 8, BIND_COUNT + 1);
    emit('behaviour', {
      step: 'binding-copy',
      label: 'EMULATOR-ONLY runtime write of the key-8 editor table',
      at: hex(BIND_RAM), bytes: bindBytes.length, newRecord: bytes(BIND_RAM + BIND_COUNT * 24, 24),
    });
    const page = Buffer.alloc(8); page.writeUInt32LE(0x6031e930, 0); page.writeUInt16LE(3, 4); l.sim.write(PAGE27 + 4, page);
    const src = Buffer.alloc(8); src.writeUInt32LE(0x6031e928, 0); src.writeUInt16LE(3, 4); l.sim.write(SOURCE + 4, src);
    writeU32(TABLE_PTR, TABLE_RAM);
    writeU32(TABLE_PTR + 4, 3);
    emit('behaviour', {
      step: 'redirects',
      label: 'EMULATOR-ONLY section-7 pointer writes, including the prerequisite page and source redirects',
      page: bytes(PAGE27 + 4, 8), source: bytes(SOURCE + 4, 8), action: bytes(TABLE_PTR, 8),
      directory: bytes(DIR, 12),
    });
    if (one && one.type === 'runtime') {
      const note = one.apply({ l, s, writeU32, writeU16, writeByte, word, bytes, readByte, native, hex, half, ROW, DESC });
      emit('behaviour', { step: 'one-change', label: 'EMULATOR-ONLY ' + one.label, explanation: one.explanation, note });
    } else if (one) {
      emit('behaviour', { step: 'one-change', label: 'EMULATOR-ONLY ' + one.label, explanation: one.explanation, type: one.type });
    }
    const idle = (ms) => { const to = l.lab_time() + ms * 1e6; while (l.lab_time() < to) s.idle_slice(Math.min(to, l.lab_time() + 50e6)); };
    const key = (k, d) => { s.key(k, d); s.camapp.pump(); };
    const press = (k) => { key(k, 'down'); idle(80); key(k, 'up'); idle(450); };
    const walk = new MenuWalk({ press, frame: () => s.frame('boundary'), draws: () => l.draw_log }, { limit: 30 });
    const shot = (name) => {
      const frame = walk.read().frame;
      const file = resolve('work/out/' + tag + '-' + name + '.png');
      write_png(file, frame[0], frame[1], words_to_rgb(frame[2]));
      return file;
    };
    const screen = () => {
      try {
        const scr = walk.read();
        const texts = scr.texts.map((t) => t.text);
        let highlight = null;
        for (const t of scr.texts) {
          try {
            const listed = walk.list(scr, t);
            if (listed && listed.cursor != null && listed.rows[listed.cursor]) { highlight = listed.rows[listed.cursor].text; break; }
          } catch { /* not a list */ }
        }
        return { texts, highlight };
      } catch (e) {
        return { texts: [], highlight: null, error: String(e && e.message ? e.message : e) };
      }
    };
    const snap = (group, fileTag) => {
      const view = screen();
      let file = null;
      try { file = shot(fileTag); } catch (e) { file = 'shot-error ' + String(e && e.message ? e.message : e); }
      const readback = cells();
      const trace = take();
      emit('observe', { step: group, file, highlight: view.highlight, texts: view.texts, cells: readback, ...trace });
      return { view, readback, trace };
    };
    idle(1200);
    press('menu');
    const seen = new Set();
    let menuRow = null;
    for (let n = 0; n < 24 && !menuRow; n++) {
      menuRow = screen().texts.find((t) => t.endsWith('AF Button'));
      if (menuRow) break;
      const sig = screen().texts.join('\n');
      if (seen.has(sig)) break;
      seen.add(sig);
      press('left');
    }
    assert.ok(menuRow, 'AF Button missing');
    walk.to([{ row: [menuRow] }]);
    idle(200);
    emit('observe', { step: 'row-bytes', row: bytes(ROW, 36), descriptor: bytes(DESC, 20) });
    state.phase = 'on';
    press('down');
    snap('down-2155', 'down-2155');
    press('down');
    snap('down-3d6f', 'down-3d6f');
    const chooserMark = totals.chooser;
    press('ok');
    const opened = snap('chooser-open', 'chooser-open');
    const nav = opts.nav ?? Array.from({ length: 9 }, () => 'right');
    const steps = [];
    for (let i = 0; i < nav.length; i++) {
      press(nav[i]);
      const got = snap('chooser-nav-' + i, 'chooser-nav-' + i);
      steps.push({ key: nav[i], texts: got.view.texts, profile: got.readback.profile });
    }
    let cancelled = null;
    let confirmed = null;
    if (opts.flow === 'commit') {
      press('menu');
      cancelled = snap('chooser-cancel', 'chooser-cancel');
      press('ok');
      snap('chooser-reopen', 'chooser-reopen');
      const again = opts.confirmNav ?? ['right', 'right', 'right'];
      for (let i = 0; i < again.length; i++) {
        press(again[i]);
        snap('chooser-confirm-nav-' + i, 'chooser-confirm-nav-' + i);
      }
      press('ok');
      confirmed = snap('chooser-confirm', 'chooser-confirm');
    }
    state.phase = 'off';
    const ownSetters = (confirmed ? confirmed.trace.setters : opened.trace.setters).filter((r) => r.id === UI);
    emit('observe', {
      step: 'done',
      chooserEntries: totals.chooser - chooserMark,
      openedTexts: opened.view.texts,
      steps,
      cancelProfile: cancelled ? cancelled.readback.profile : null,
      confirmProfile: confirmed ? confirmed.readback.profile : null,
      confirmSetters: confirmed ? confirmed.trace.setters.filter((r) => r.id === UI) : ownSetters,
      priorityHelp: opened.view.texts.some((t) => String(t).includes('selected AF target position')),
    });
  } catch (e) {
    emit('observe', { step: 'boundary', error: String(e && e.stack ? e.stack : e) });
    process.exitCode = 1;
  } finally {
    if (sessionPlayer && sessionPlayer.session) sessionPlayer.close_session();
    mkdirSync(resolve('work/out'), { recursive: true });
    writeFileSync(outPath, lines.join('\n') + (lines.length ? '\n' : ''));
  }
}
